with valid as (select id, store_name, city, opened_date, initcap(trim(store_name)) as store_name_title, coalesce(region, 'OTHER') as region_filled from stores where opened_date >= date '2023-02-17' and store_name is null) select *, row_number() over w_hist as seq_no, row_number() over (partition by city order by opened_date, id) as row_seq from valid window w_hist as (partition by city order by opened_date desc, id)
